const items = $input.all();
const out = [];

for (const item of items) {
  const j = item.json;

  // Get the raw AI text output
  let rawText = '';
  if (j.output && j.output[0] && j.output[0].content && j.output[0].content[0]) {
    rawText = j.output[0].content[0].text || '';
  } else if (j.text) {
    rawText = j.text;
  } else if (typeof j.output === 'string') {
    rawText = j.output;
  }

  // Clean markdown wrappers if present
  rawText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  // Parse the JSON
  let parsed = {};
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    // If JSON parse fails, try to find JSON object in the string
    const match = rawText.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
    }
  }

  // Extract variants
  const variantA = parsed.variant_a || '';
  const variantB = parsed.variant_b || '';
  const variantC = parsed.variant_c || '';
  const roundType = parsed.round_type || '';

  // Randomly pick one variant for the icebreaker field
  const variants = [
    { letter: 'A', text: variantA },
    { letter: 'B', text: variantB },
    { letter: 'C', text: variantC }
  ].filter(v => v.text);

  const picked = variants[Math.floor(Math.random() * variants.length)];

  out.push({
    json: {
      icebreaker: picked.text,
      icebreakerVariant: picked.letter,
      roundType: roundType,
      variant_a: variantA,
      variant_b: variantB,
      variant_c: variantC
    }
  });
}

return out;

