const ex = $('Get Signals Rows').item.json || {};
const wh = $('Webhook2').item.json.body || {};
const email = ((wh.result && wh.result.email) || '').toLowerCase().trim();
const normDom = d => (d||'').toString().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'').trim();
const dom = normDom((wh.input && wh.input.domain) || ex.companyWebsite || '');
const exKey = (ex.dedupKey||'').trim();
const now = Date.now();
let suppressed = false;
for (const r of $('Get Suppression rows1').all()) {
  const j = r.json || {};
  const dncRaw = String(j.doNotContact==null?'':j.doNotContact).trim().toLowerCase();
  const isDnc = dncRaw==='true'||dncRaw==='yes'||dncRaw==='1';
  let hold = false; if (j.contactAfterDate){ const t=Date.parse(j.contactAfterDate); if(!isNaN(t)&&t>now) hold=true; }
  if (!(isDnc||hold)) continue;
  const se=(j.email||'').toLowerCase().trim(); const sd=normDom(j.domain); const sk=(j.dedupKey||'').trim();
  if ((se&&se===email)||(sd&&sd===dom)||(sk&&sk===exKey)) { suppressed=true; break; }
}
const already = String(ex.addedToCampaign).toLowerCase()==='true' || (ex.emailStatus||'')==='found';
let _gate = 'proceed';
if (suppressed) _gate='suppress'; else if (already) _gate='backup';
return [{ json: { ...ex, _gate } }];
